export const getLoginUrl = () => {




  return `/api/v1/auth/login`
}

/**
 * Нужен CSRF-токен: cookie XSRF-TOKEN из GET /api/v1/auth/csrf и её значение в заголовке X-XSRF-TOKEN. При успехе — новая cookie сессии DENTIFY_SESSION (HttpOnly, Secure, SameSite=Lax; с rememberMe — на 30 дней, иначе до закрытия браузера) и новый CSRF-токен. Ответ — как GET /api/v1/me: при одном активном членстве с одним филиалом клиника и филиал уже выбраны (context), иначе context пустой и интерфейс показывает выбор клиники. Неверный пароль и неизвестный логин — один ответ 401 iam.login.invalid. Лимиты: 5 неверных попыток на логин за 15 минут, затем 429 на 15 минут даже с верным паролем; 30 попыток с IP в минуту.
 * @summary Войти по телефону или e-mail и паролю
 */
export const login = async (loginRequest: LoginRequest, options?: Parameters<typeof http>[1]): Promise<MeResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return http<MeResponse>(getLoginUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(loginRequest)
  }
);}





